using AdielSystem.Api.Security;
using AdielSystem.Application.Expenses;
namespace AdielSystem.Api.Endpoints;
public static class ExpenseEndpoints
{
 public static RouteGroupBuilder MapExpenseEndpoints(this RouteGroupBuilder group){var expenses=group.MapGroup("/expenses").WithTags("Expenses").RequireRateLimiting(SecurityConstants.OwnerRateLimitPolicy);expenses.MapGet("/",async(string? search,string? status,bool? archivedOnly,int? page,int? pageSize,ExpenseService service,CancellationToken token)=>Results.Ok(await service.ListAsync(search,status,archivedOnly??false,page??1,pageSize??100,token))).WithName("ListExpenses");expenses.MapGet("/{id:guid}",async(Guid id,ExpenseService service,CancellationToken token)=>Results.Ok(await service.GetAsync(id,token))).WithName("GetExpense");expenses.MapPost("/",async(SaveExpenseRequest request,ExpenseService service,CancellationToken token)=>{var value=await service.CreateAsync(request,token);return Results.CreatedAtRoute("GetExpense",new{id=value.Id},value);}).WithName("CreateExpense");expenses.MapPut("/{id:guid}",async(Guid id,SaveExpenseRequest request,ExpenseService service,CancellationToken token)=>Results.Ok(await service.UpdateAsync(id,request,token))).WithName("UpdateExpense");expenses.MapPost("/{id:guid}/status",async(Guid id,ChangeExpenseStatusRequest request,ExpenseService service,CancellationToken token)=>Results.Ok(await service.ChangeStatusAsync(id,request,token))).WithName("ChangeExpenseStatus");expenses.MapPost("/{id:guid}/archive",async(Guid id,ChangeExpenseArchiveRequest request,ExpenseService service,CancellationToken token)=>Results.Ok(await service.ArchiveAsync(id,request,token))).WithName("ArchiveExpense");expenses.MapPost("/{id:guid}/restore",async(Guid id,ChangeExpenseArchiveRequest request,ExpenseService service,CancellationToken token)=>Results.Ok(await service.RestoreAsync(id,request,token))).WithName("RestoreExpense");group.MapPost("/purchase-orders/{id:guid}/expense",async(Guid id,ExpenseService service,CancellationToken token)=>Results.Ok(await service.GenerateFromPurchaseOrderAsync(id,token))).WithName("GenerateExpenseFromPurchaseOrder").RequireRateLimiting(SecurityConstants.OwnerRateLimitPolicy);return group;}
}
